args.command:
python - <<'PY'
import os
terms=('attachment','stale','refresh','external','ticker','interval')
for root, dirs, files in os.walk('.'):
    dirs[:] = [d for d in dirs if d != '.git' and d != 'web']
    for f in files:
        p=os.path.join(root,f)
        try: s=open(p, errors='ignore').read().splitlines()
        except: continue
        for i,l in enumerate(s,1):
            if any(t in l.lower() for t in terms): print(f'{p}:{i}:{l}')
PY

